# a healthy set: time each write concern three times
docker compose -f env/mongo-rs.yml exec mongo1 mongosh sfz --quiet --eval '
  db.balances.insertOne({_id: "acct-1001", balanceMinor: 10000}, {writeConcern: {w: "majority"}});
  for (const w of [1, "majority", 1, "majority", 1, "majority"]) {
    const t = Date.now();
    db.balances.updateOne({_id: "acct-1001"}, {$inc: {balanceMinor: -100}}, {writeConcern: {w}});
    print("w:" + w, Date.now() - t, "ms");
  }'

# both secondaries stop applying replication: the primary is as good as cut off
for m in mongo2 mongo3; do docker compose -f env/mongo-rs.yml exec $m mongosh --quiet --eval 'db.fsyncLock().ok'; done

# the same write and three reads, each with a 2-second limit
docker compose -f env/mongo-rs.yml exec mongo1 mongosh sfz --quiet --eval '
  for (const w of [1, "majority"]) {
    const t = Date.now();
    try { db.balances.updateOne({_id: "acct-1001"}, {$inc: {balanceMinor: -2500}}, {writeConcern: {w, wtimeout: 2000}}); print("w:" + w, "ok", Date.now() - t, "ms") }
    catch (e) { print("w:" + w, e.codeName, Date.now() - t, "ms") }
  }
  for (const level of ["local", "majority", "linearizable"]) {
    const t = Date.now();
    try { const d = db.balances.find({_id: "acct-1001"}).readConcern(level).maxTimeMS(2000).next(); print(level, d.balanceMinor, Date.now() - t, "ms") }
    catch (e) { print(level, e.codeName, Date.now() - t, "ms") }
  }'

for m in mongo2 mongo3; do docker compose -f env/mongo-rs.yml exec $m mongosh --quiet --eval 'db.fsyncUnlock().ok'; done
docker compose -f env/mongo-rs.yml down -v

