fun satisfies(h: History, model: Model): Boolean {
    fun view(p: String) = h.ops.filter { it.kind == Kind.WRITE || it.process == p }
    return when (model) {
        Model.LINEARIZABLE -> Search.exists(h.ops, ::realTime)
        Model.SEQUENTIAL -> Search.exists(h.ops, ::programOrder)
        Model.CAUSAL -> causalOrder(h).let { before -> h.processes.all { Search.exists(view(it), before) } }
        Model.READ_YOUR_WRITES -> h.processes.all { p ->
            Search.exists(view(p)) { a, b -> a.process == p && b.process == p && a.kind == Kind.WRITE && b.kind == Kind.READ && programOrder(a, b) }
        }
        Model.MONOTONIC_READS -> h.processes.all { p ->
            Search.exists(view(p)) { a, b -> a.process == p && b.process == p && a.kind == Kind.READ && b.kind == Kind.READ && programOrder(a, b) }
        }
        Model.EVENTUAL -> true
    }
}
